for k in [0.5,1,2,3]:
    for q in [0,1,2,3]:
        lib[f'exp(-{k}/e)T{q}']=np.exp(-k/eps)*T**q
        lib[f'exp(-{k}e)T{q}']=np.exp(-k*eps)*T**q
        lib[f'log(e)T{q}']=np.log(eps)*T**q
        lib[f'exp(-{k}T)e{q}']=np.exp(-k*T)*eps**q if q>=0 else None
lib={k:v for k,v in lib.items() if v is not None}
keys=list(lib)
def sse(c3,extra):
    A=np.column_stack([1/eps, eps/(1+c3*eps)*T**3]+[lib[x] for x in extra])
    c,_,_,_=np.linalg.lstsq(A,s,rcond=None)
    return np.mean((s-A@c)**2)/np.var(s)
